"use client"

import React from "react"
import { FlowShell } from "../_shared/FlowShell"
import { useFlowState } from "../_shared/useFlowState"
import { TABBY_INITIAL, TABBY_STEPS, TABBY_GREEN, TabbyData, TabbyStepProps } from "./schema"
import { Splash } from "./steps/Splash"
import { Country } from "./steps/Country"
import { Marketing } from "./steps/Marketing"
import { Phone } from "./steps/Phone"
import { OTP } from "./steps/OTP"
import { PIN } from "./steps/PIN"
import { TrustDevice } from "./steps/TrustDevice"
import { Privacy } from "./steps/Privacy"
import { Success } from "./steps/Success"

export default function TabbyFlowPage() {
  const flow = useFlowState<TabbyData>({
    totalSteps: TABBY_STEPS.length,
    initialData: TABBY_INITIAL,
  })

  const stepProps: TabbyStepProps = {
    data: flow.data,
    patch: flow.patch,
    next: flow.next,
    back: flow.back,
    goTo: flow.goTo,
  }

  const stepKey = TABBY_STEPS[flow.step]

  // Step-specific phone-frame tinting
  const isSplash = stepKey === "splash"
  const phoneBackground = isSplash ? TABBY_GREEN : "var(--atlas-background)"
  const statusBarTint = "dark" as const

  return (
    <FlowShell
      title="Tabby — iOS onboarding"
      step={flow.step}
      totalSteps={TABBY_STEPS.length}
      onReset={flow.reset}
      phoneBackground={phoneBackground}
      statusBarTint={statusBarTint}
      homeIndicatorTint="dark"
    >
      {stepKey === "splash" && <Splash {...stepProps} />}
      {stepKey === "country" && <Country {...stepProps} />}
      {stepKey === "marketing" && <Marketing {...stepProps} />}
      {stepKey === "phone" && <Phone {...stepProps} />}
      {stepKey === "otp" && <OTP {...stepProps} />}
      {stepKey === "pin" && <PIN {...stepProps} />}
      {stepKey === "trust" && <TrustDevice {...stepProps} />}
      {stepKey === "privacy" && <Privacy {...stepProps} />}
      {stepKey === "success" && <Success {...stepProps} />}
    </FlowShell>
  )
}

"use client"

import React from "react"

/**
 * Shared screen chrome for Tabby step screens — a thin header row
 * with optional back and close affordances.
 */
export function ScreenHeader({
  onBack,
  onClose,
  closeLabel = "Close",
  rightSlot,
}: {
  onBack?: () => void
  onClose?: () => void
  closeLabel?: string
  rightSlot?: React.ReactNode
}) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        height: 44,
      }}
    >
      <div>
        {onBack && (
          <button
            type="button"
            aria-label="Back"
            onClick={onBack}
            style={iconBtnStyle}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden>
              <path
                d="M15 18l-6-6 6-6"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        )}
      </div>
      <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
        {rightSlot}
        {onClose && (
          <button
            type="button"
            aria-label={closeLabel}
            onClick={onClose}
            style={iconBtnStyle}
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden>
              <path
                d="M6 6l12 12M6 18L18 6"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
              />
            </svg>
          </button>
        )}
      </div>
    </div>
  )
}

const iconBtnStyle: React.CSSProperties = {
  width: 36,
  height: 36,
  display: "inline-flex",
  alignItems: "center",
  justifyContent: "center",
  background: "transparent",
  border: 0,
  cursor: "pointer",
  color: "var(--atlas-foreground)",
  borderRadius: "var(--atlas-radius-full)",
}

/**
 * Big circular illustration disc — used by trust/privacy/PIN intro screens.
 */
export function IllustrationDisc({
  emoji,
  tint = "var(--atlas-primary-subtle)",
  fg = "var(--atlas-primary)",
}: {
  emoji: string
  tint?: string
  fg?: string
}) {
  return (
    <div
      aria-hidden
      style={{
        width: 56,
        height: 56,
        borderRadius: "var(--atlas-radius-full)",
        background: tint,
        color: fg,
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: 28,
      }}
    >
      {emoji}
    </div>
  )
}

"use client"

import React from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { TabbyStepProps } from "../schema"

/**
 * Success — simplified "stores" home that lands after onboarding.
 * Mirrors the last screen of the source flow at a high level only.
 */
export function Success({ goTo }: TabbyStepProps) {
  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", overflowY: "auto" }}>
      {/* Header search */}
      <div style={{ padding: "var(--atlas-spacing-4) var(--atlas-spacing-5)" }}>
        <Input
          placeholder="Stores or products"
          leadingIcon={<span aria-hidden style={{ fontSize: 14 }}>🔍</span>}
          size="md"
        />
      </div>

      {/* Quick links */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "var(--atlas-spacing-3)",
          padding: "0 var(--atlas-spacing-5)",
        }}
      >
        <QuickLink emoji="🛒" title="All stores" sub="Shop and split" />
        <QuickLink emoji="🏷️" title="Deals" sub="Discounts up to 30%" />
      </div>

      {/* Categories row */}
      <div
        style={{
          display: "flex",
          gap: "var(--atlas-spacing-3)",
          padding: "var(--atlas-spacing-5)",
          overflowX: "auto",
        }}
      >
        {[
          { emoji: "💸", label: "Customise your Tabby" },
          { emoji: "📱", label: "Mobile" },
          { emoji: "💍", label: "Jewelry" },
        ].map((c) => (
          <div key={c.label} style={{ minWidth: 110 }}>
            <Card variant="outlined" size="sm">
              <CardContent>
                <div style={{ fontSize: 24 }}>{c.emoji}</div>
                <div
                  style={{
                    marginBlockStart: 6,
                    fontSize: "var(--atlas-font-size-xs)",
                    fontWeight: 600,
                    lineHeight: 1.3,
                  }}
                >
                  {c.label}
                </div>
              </CardContent>
            </Card>
          </div>
        ))}
      </div>

      {/* Invite friends card */}
      <div style={{ padding: "0 var(--atlas-spacing-5)" }}>
        <Card variant="filled">
          <CardContent>
            <div style={{ display: "flex", gap: "var(--atlas-spacing-3)", alignItems: "center" }}>
              <span aria-hidden style={{ fontSize: 28 }}>🏠</span>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: "var(--atlas-font-size-sm)", fontWeight: 600 }}>
                  Earn up to ₪200 by inviting friends to Tabby
                </div>
                <a
                  href="#"
                  onClick={(e) => e.preventDefault()}
                  style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-primary)", fontWeight: 600 }}
                >
                  Learn more
                </a>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Stores for you */}
      <div
        style={{
          padding: "var(--atlas-spacing-5) var(--atlas-spacing-5) 0",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <strong style={{ fontSize: "var(--atlas-font-size-base)" }}>Stores For You</strong>
        <a
          href="#"
          onClick={(e) => e.preventDefault()}
          style={{ fontSize: "var(--atlas-font-size-sm)", color: "var(--atlas-primary)", fontWeight: 600 }}
        >
          View all
        </a>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          gap: "var(--atlas-spacing-2)",
          padding: "var(--atlas-spacing-3) var(--atlas-spacing-5)",
        }}
      >
        {["Cole", "Glamzale", "Ecco", "Mumzw"].map((store) => (
          <div
            key={store}
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 4,
            }}
          >
            <div
              style={{
                width: 56,
                height: 56,
                borderRadius: "var(--atlas-radius-full)",
                background: "var(--atlas-background-muted)",
              }}
            />
            <span style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-foreground-muted)" }}>{store}</span>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }} />

      {/* Reset CTA so user can run the flow again */}
      <div style={{ padding: "var(--atlas-spacing-3) var(--atlas-spacing-5)" }}>
        <Badge size="sm" variant="success" dot>
          You&apos;re all set
        </Badge>
        <div style={{ marginBlockStart: "var(--atlas-spacing-2)" }}>
          <Button variant="outline" size="sm" onClick={() => goTo(0)}>
            Run the flow again
          </Button>
        </div>
      </div>

      {/* Bottom tab bar */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          padding: "var(--atlas-spacing-3) var(--atlas-spacing-4) var(--atlas-spacing-6)",
          borderTop: "1px solid var(--atlas-border)",
          background: "var(--atlas-background)",
        }}
      >
        {[
          { icon: "🔍", label: "Discover", active: true },
          { icon: "🛍️", label: "Shop" },
          { icon: "💳", label: "Money" },
          { icon: "👤", label: "Profile" },
        ].map((t) => (
          <div
            key={t.label}
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 2,
              color: t.active ? "var(--atlas-foreground)" : "var(--atlas-foreground-muted)",
            }}
          >
            <span aria-hidden style={{ fontSize: 18 }}>{t.icon}</span>
            <span style={{ fontSize: 10, fontWeight: 600 }}>{t.label}</span>
          </div>
        ))}
      </div>
    </div>
  )
}

function QuickLink({ emoji, title, sub }: { emoji: string; title: string; sub: string }) {
  return (
    <Card variant="outlined" size="sm" interactive>
      <CardContent>
        <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-2)" }}>
          <span aria-hidden style={{ fontSize: 18 }}>{emoji}</span>
          <div style={{ fontSize: "var(--atlas-font-size-sm)", fontWeight: 600 }}>{title}</div>
        </div>
        <div style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-foreground-muted)", marginBlockStart: 2 }}>
          {sub}
        </div>
      </CardContent>
    </Card>
  )
}

#!/usr/bin/env node
/**
 * Atlas Design System — Token Governance Lint
 *
 * Walks packages/ui-web/src/ and app/ for hardcoded colour/spacing values
 * that should reference --atlas-* CSS custom properties instead.
 *
 * Rules:
 *   1. No hex colour literals (#abc, #aabbcc, #aabbccdd)
 *   2. No rgb() / rgba() calls (outside packages/tokens/)
 *   3. No oklch() calls (outside packages/tokens/)
 *   4. No hsl() / hsla() calls (outside packages/tokens/)
 *
 * Allow-list:
 *   - Lines containing "token-lint-disable-next-line" suppress the NEXT line only.
 *   - Files in packages/tokens/ are always skipped.
 *   - Test files (*.test.*) and governance scripts are skipped.
 *   - Storybook / example files are skipped.
 *
 * Usage:
 *   node packages/governance/token-lint.mjs
 *   node packages/governance/token-lint.mjs --fix   (future — not yet implemented)
 *
 * Exit codes:
 *   0  — no violations
 *   1  — violations found
 */

import fs from "fs"
import path from "path"
import { fileURLToPath } from "url"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.resolve(__dirname, "../..")

// ─── Config ──────────────────────────────────────────────────────────────────

const SCAN_DIRS = [
  path.join(ROOT, "packages/ui-web/src"),
  path.join(ROOT, "app"),
]

const SKIP_DIRS = new Set([
  "node_modules",
  ".next",
  ".git",
  "packages/tokens",
  "packages/governance",
])

const SKIP_FILE_PATTERNS = [
  /\.test\.[tj]sx?$/,
  /\.spec\.[tj]sx?$/,
  /\.stories\.[tj]sx?$/,
  /vitest\.config/,
]

const SCAN_EXTENSIONS = new Set([".ts", ".tsx", ".css"])

// ─── Rules ───────────────────────────────────────────────────────────────────

const RULES = [
  {
    id: "no-hex-color",
    description: "Hardcoded hex colour — use an --atlas-* token instead",
    // Matches #RGB, #RRGGBB, #RRGGBBAA — but not CSS ID selectors or comments
    pattern: /(?<![/]{2}[^\n]*)(?:^|[\s:,(])(#[0-9a-fA-F]{3,8})\b/,
    // Skip lines that are pure CSS selectors (e.g. #app { )
    skip: (line) => /^#[\w-]+\s*[{,]/.test(line.trim()),
  },
  {
    id: "no-rgb",
    description: "Hardcoded rgb()/rgba() — use an --atlas-* token instead",
    pattern: /\brgba?\s*\(/,
    skip: () => false,
  },
  {
    id: "no-oklch-raw",
    description: "Raw oklch() outside tokens package — use an --atlas-* token instead",
    pattern: /\boklch\s*\(/,
    // Allow oklch(1 0 0) / oklch(0 0 0) — achromatic white/black anchors used
    // legitimately inside color-mix() as neutral mix targets. Any chroma (C > 0)
    // would indicate a hardcoded brand colour that should become a token.
    skip: (line) => /\bcolor-mix\(in\s+oklch,/.test(line) &&
                    /oklch\(\s*[01]\.?\d*\s+0\s+0\s*\)/.test(line),
  },
  {
    id: "no-hsl",
    description: "Hardcoded hsl()/hsla() — use an --atlas-* token instead",
    pattern: /\bhsla?\s*\(/,
    skip: () => false,
  },
]

// ─── Walker ──────────────────────────────────────────────────────────────────

function* walkFiles(dir) {
  if (!fs.existsSync(dir)) return
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name)
    if (entry.isDirectory()) {
      const rel = path.relative(ROOT, fullPath)
      if ([...SKIP_DIRS].some((d) => rel.startsWith(d) || entry.name === d)) continue
      yield* walkFiles(fullPath)
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name)
      if (!SCAN_EXTENSIONS.has(ext)) continue
      if (SKIP_FILE_PATTERNS.some((p) => p.test(entry.name))) continue
      yield fullPath
    }
  }
}

// ─── Lint ────────────────────────────────────────────────────────────────────

const violations = []

for (const dir of SCAN_DIRS) {
  for (const filePath of walkFiles(dir)) {
    const rel = path.relative(ROOT, filePath)
    const lines = fs.readFileSync(filePath, "utf8").split("\n")

    let suppressNext = false
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]
      const lineNo = i + 1

      if (line.includes("token-lint-disable-next-line")) {
        suppressNext = true
        continue
      }

      if (suppressNext) {
        suppressNext = false
        continue
      }

      for (const rule of RULES) {
        if (rule.skip(line)) continue
        if (rule.pattern.test(line)) {
          violations.push({ file: rel, line: lineNo, rule: rule.id, text: line.trim() })
        }
      }
    }
  }
}

// ─── Report ──────────────────────────────────────────────────────────────────

if (violations.length === 0) {
  console.log("✅ Token lint: 0 violations")
  process.exit(0)
} else {
  console.error(`❌ Token lint: ${violations.length} violation${violations.length === 1 ? "" : "s"} found\n`)
  let lastFile = null
  for (const v of violations) {
    if (v.file !== lastFile) {
      console.error(`  ${v.file}`)
      lastFile = v.file
    }
    console.error(`    [${v.rule}] line ${v.line}: ${v.text.slice(0, 120)}`)
  }
  console.error(`
To suppress a single line, add a comment on the preceding line:
  /* token-lint-disable-next-line */
`)
  process.exit(1)
}

