export type SendMoneyData = {
  recipient: Recipient | null
  sendAmount: string
  confirmOpen: boolean
  sent: boolean
}

export const SEND_MONEY_INITIAL: SendMoneyData = {
  recipient: null,
  sendAmount: "",
  confirmOpen: false,
  sent: false,
}

export const SEND_MONEY_STEPS = ["recipient", "amount", "review"] as const

export type SendMoneyStepKey = (typeof SEND_MONEY_STEPS)[number]

export type SendMoneyStepProps = {
  data: SendMoneyData
  patch: (partial: Partial<SendMoneyData>) => void
  next: () => void
  back: () => void
  goTo: (index: number) => void
  reset: () => void
}

export function feeFor(amount: number): number {
  if (!Number.isFinite(amount) || amount <= 0) return 0
  return FEE_FLAT + amount * FEE_RATE
}

export function rateFor(currency: string): number {
  return FX_RATES[currency] ?? 1
}

export function recipientGets(amount: number, currency: string): number {
  if (!Number.isFinite(amount) || amount <= 0) return 0
  return amount * rateFor(currency)
}

export function maskAccount(last4: string): string {
  return `•••• ${last4}`
}

