"use client"

import React, { useMemo, useState } from "react"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { RECENT_RECIPIENTS, Recipient, SendMoneyStepProps, maskAccount } from "../schema"

export function RecipientStep({ data, patch, next }: SendMoneyStepProps) {
  const [query, setQuery] = useState("")

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return RECENT_RECIPIENTS
    return RECENT_RECIPIENTS.filter((r) => r.name.toLowerCase().includes(q))
  }, [query])

  const handleSelect = (recipient: Recipient) => {
    patch({ recipient })
    next()
  }

  return (
    <div
      style={{
        flex: 1,
        display: "flex",
        flexDirection: "column",
        padding: "var(--atlas-spacing-4) var(--atlas-spacing-5) var(--atlas-spacing-5)",
        gap: "var(--atlas-spacing-4)",
        overflowY: "auto",
      }}
    >
      <h1
        style={{
          margin: 0,
          fontSize: "var(--atlas-font-size-2xl)",
          fontWeight: 700,
          letterSpacing: "-0.01em",
        }}
      >
        Send money
      </h1>

      <Input
        placeholder="Search recipients"
        leadingIcon={<span aria-hidden style={{ fontSize: 14 }}>🔍</span>}
        size="lg"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        aria-label="Search recipients"
      />

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <span
          style={{
            fontSize: "var(--atlas-font-size-xs)",
            fontWeight: 600,
            color: "var(--atlas-foreground-muted)",
            textTransform: "uppercase",
            letterSpacing: "0.04em",
          }}
        >
          Recent recipients
        </span>

        {filtered.length === 0 && (
          <p
            style={{
              margin: 0,
              fontSize: "var(--atlas-font-size-sm)",
              color: "var(--atlas-foreground-muted)",
            }}
          >
            No recipients match &quot;{query}&quot;.
          </p>
        )}

        <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
          {filtered.map((recipient) => (
            <Card
              key={recipient.id}
              variant="outlined"
              size="sm"
              interactive
              onClick={() => handleSelect(recipient)}
              role="button"
              aria-label={`Send to ${recipient.name}`}
            >
              <CardContent>
                <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
                  <div
                    aria-hidden
                    style={{
                      width: 40,
                      height: 40,
                      borderRadius: "var(--atlas-radius-full)",
                      background: "var(--atlas-background-muted)",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      fontSize: 18,
                      fontWeight: 700,
                      flexShrink: 0,
                    }}
                  >
                    {recipient.name.charAt(0)}
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: "var(--atlas-font-size-sm)", fontWeight: 600 }}>
                      {recipient.name}
                    </div>
                    <div
                      style={{
                        fontSize: "var(--atlas-font-size-xs)",
                        color: "var(--atlas-foreground-muted)",
                      }}
                    >
                      {maskAccount(recipient.accountLast4)}
                    </div>
                  </div>
                  <Badge size="sm" variant="secondary">
                    <span aria-hidden style={{ marginInlineEnd: 4 }}>{recipient.flag}</span>
                    {recipient.currency}
                  </Badge>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    </div>
  )
}

