"use client"

import React, { useMemo } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import {
  SEND_CURRENCY,
  SendMoneyStepProps,
  feeFor,
  rateFor,
  recipientGets,
} from "../schema"

export function AmountStep({ data, patch, next, back }: SendMoneyStepProps) {
  const recipient = data.recipient
  const currency = recipient?.currency ?? SEND_CURRENCY

  const amountValue = useMemo(() => {
    const parsed = parseFloat(data.sendAmount)
    return Number.isFinite(parsed) ? parsed : 0
  }, [data.sendAmount])

  const isValid = data.sendAmount.trim() !== "" && amountValue > 0

  const fee = feeFor(amountValue)
  const rate = rateFor(currency)
  const total = amountValue + fee
  const gets = recipientGets(amountValue, currency)

  const handleAmountChange = (raw: string) => {
    // Allow only digits and a single decimal point
    const cleaned = raw.replace(/[^0-9.]/g, "")
    patch({ sendAmount: cleaned })
  }

  const handleContinue = () => {
    if (!isValid) return
    next()
  }

  return (
    <div
      style={{
        flex: 1,
        display: "flex",
        flexDirection: "column",
        padding: "var(--atlas-spacing-4) var(--atlas-spacing-5) var(--atlas-spacing-5)",
        gap: "var(--atlas-spacing-4)",
        overflowY: "auto",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-2)" }}>
        <Button size="sm" variant="ghost" onClick={back} aria-label="Back">
          ←
        </Button>
        <h1
          style={{
            margin: 0,
            fontSize: "var(--atlas-font-size-xl)",
            fontWeight: 700,
          }}
        >
          Enter amount
        </h1>
      </div>

      {/* You send */}
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <Label htmlFor="send-amount">You send</Label>
        <Input
          id="send-amount"
          inputMode="decimal"
          size="lg"
          placeholder="0.00"
          value={data.sendAmount}
          onChange={(e) => handleAmountChange(e.target.value)}
          prefix={SEND_CURRENCY}
          invalid={data.sendAmount.trim() !== "" && !isValid}
        />
      </div>

      {/* Recipient gets */}
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <Label htmlFor="recipient-gets">Recipient gets</Label>
        <Input
          id="recipient-gets"
          size="lg"
          readOnly
          value={gets > 0 ? gets.toFixed(2) : ""}
          placeholder="0.00"
          prefix={currency}
        />
      </div>

      {/* Fee breakdown */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-2)",
          padding: "var(--atlas-spacing-3)",
          background: "var(--atlas-background-muted)",
          borderRadius: "var(--atlas-radius-md)",
        }}
      >
        <Row label="Fee" value={`${SEND_CURRENCY} ${fee.toFixed(2)}`} />
        <Row label="Exchange rate" value={`1 ${SEND_CURRENCY} = ${rate.toFixed(4)} ${currency}`} />
        <Row label="Total to pay" value={`${SEND_CURRENCY} ${total.toFixed(2)}`} strong />
      </div>

      <Alert variant="info" title="Arrival time">
        Money usually arrives within minutes, but can take up to 1 business day.
      </Alert>

      <div style={{ flex: 1 }} />

      <Button variant="primary" size="lg" disabled={!isValid} onClick={handleContinue} style={{ width: "100%" }}>
        Continue
      </Button>
    </div>
  )
}

function Row({ label, value, strong }: { label: string; value: string; strong?: boolean }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between" }}>
      <span
        style={{
          fontSize: "var(--atlas-font-size-sm)",
          color: "var(--atlas-foreground-muted)",
        }}
      >
        {label}
      </span>
      <span
        style={{
          fontSize: "var(--atlas-font-size-sm)",
          fontWeight: strong ? 700 : 500,
        }}
      >
        {value}
      </span>
    </div>
  )
}

